$nonMain=@($b.objects|Where-Object {$_.stem -cne 'main'});$objects=@($nonMain|ForEach-Object {$_.object});if($nonMain.Count -ne 85 -or @($b.objects|Where-Object {$_.stem -ceq 'main'}).Count -ne 1 -or @($objects.path|Sort-Object -Unique).Count -ne 85 -or @(Compare-Object ($objects.path|Sort-Object) ($h.objects.path|Sort-Object)).Count){throw 'Main helper and fresh build85-object membership differs'}
