VerifyBase;$cc=PassedCall $h.compile_call;$lc=PassedCall $h.link_call;[void](PassedCall $b.project_call)
$declaration=ReadJson $fixtureNote;$readerCpp=Join-Path $t 'support\upl_cpu_public_native_r1.cpp';$readerNote=Join-Path $t 'notes\upl_cpu_public_native_r1.json';$fixtureIdentity=Entry $cpp;$fixtureDeclaration=Entry $fixtureNote;$reader=Entry $readerCpp
if($fixtureIdentity.bytes -ne 31108 -or $fixtureIdentity.sha256 -ine '48f89493d78ab9e1e330ec289492067d655213305cecfe41a4a3dfc8351c6055' -or $fixtureDeclaration.sha256 -ine '020effe94e085b80bf86e9906097a17c85f144b06b6add03f1b299992c522239' -or $reader.bytes -ne $declaration.immutable_include.bytes -or $reader.sha256 -ine $declaration.immutable_include.sha256){throw 'Reviewed actual-audit/immutable-reader author identity differs'}
$authors=@($PSCommandPath,$note,$cpp,$fixtureNote,$readerCpp,$readerNote)|ForEach-Object {Entry $_};$debugGate=$null
if($Configuration -eq 'ReleaseCPU'){$debugPath=Join-Path $logs 'upl_gravity_wall_actual_DebugCPU_r1.helper.json';$debug=ReadJson $debugPath;if(!$debug.passed -or $debug.fixture -cne 'GravityTangentWallActual' -or $debug.configuration -cne 'DebugCPU' -or $debug.CPU_non_main_objects -ne 85 -or $debug.link_object_count -ne 86 -or !$debug.exact_link_closure_verified -or $debug.program_run -ne $false){throw 'New actual-audit Debug helper build must pass before Release helper build'};Verify @($debug.program,$debug.compile_call,$debug.link_call);Verify $debug.author_files;$debugGate=Entry $debugPath}
$environmentRecord=ReadJson $h.environment_source.path;if(!$environmentRecord.passed -or $environmentRecord.configuration -cne $Configuration -or $environmentRecord.environment.exit_code -ne 0 -or $h.environment.exit_code -ne 0){throw 'Hash-bound actual Gamma environment provenance required'}
foreach($key in @('INCLUDE','LIB','VCToolsInstallDir','WindowsSdkDir','WindowsSDKVersion')){$value=[string]$h.environment.selected.$key;if([string]::IsNullOrWhiteSpace($value) -or $value -cne [string]$environmentRecord.environment.selected.$key){throw "Successful r2 helper must carry its actual nonempty selected environment: $key"};[Environment]::SetEnvironmentVariable($key,$value,'Process')};$env:PATH=([IO.Path]::GetDirectoryName($cc.program.path))+';'+$env:PATH
$oldCpp=Join-Path $t 'support\upl_gravity_wall_cpu_r1.cpp';$oldDir=Split-Path -Parent $h.program.path;$obj=Join-Path $folder 'helper.obj';$exe=Join-Path $folder 'upl_gravity_wall_actual_r1.exe';$compile=@();$sourceRemap=0;$fo=0;$fd=0;$deps=0
foreach($a in $cc.arguments){if($a -ieq $oldCpp){$compile+=$cpp;$sourceRemap++}elseif($a.StartsWith('/Fo',[StringComparison]::OrdinalIgnoreCase)){$compile+='/Fo'+$obj;$fo++}elseif($a.StartsWith('/Fd',[StringComparison]::OrdinalIgnoreCase)){$compile+='/Fd'+(Join-Path $folder 'compile.pdb');$fd++}elseif($a -ieq (Join-Path $oldDir 'compile.dependencies.json')){$compile+=Join-Path $folder 'compile.dependencies.json';$deps++}else{$compile+=$a}}
if($sourceRemap -ne 1 -or $fo -ne 1 -or $fd -ne 1 -or $deps -ne 1 -or $compile -notcontains '/std:c++17' -or $compile -notcontains '/fp:precise'){throw 'Exact source/Fo/Fd/dependency remaps and inherited CPU flags required'}
